// mairo by erpowel (manz subeme el sueldo.)

run_speed = 0
drifting = false
crouch_jump = false
started_jumping = false

create()
    GetComponent("WalkAnim").Play("idle")
end

frame()
    is_moving = false

    // agachado
    if (IsOnFloor()):
        crouching = CheckInput("crouch")
        crouch_jump = false
        started_jumping = false
    else
        drifting = false

        if (crouch_jump):
            if (GetComponent("").speed_y < 0):
                crouching = true
            else
                crouching = CheckInput("crouch")
            end
        else
            crouching = false
        end
    end

    // detectar si hay cambio de direccion en suelo 
    if (IsOnFloor() and !crouching):
        if (run_speed > 10):
            if (GetComponent("").speed_x > 50 and CheckInput("left")):
                drifting = true
            elif (GetComponent("").speed_x < -50 and CheckInput("right")):
                drifting = true
            end
        end
    end

    // cancelar estado de derrape cuando mairo frena por completo
    if (GetComponent("").speed_x >= -50 and GetComponent("").speed_x <= 50):
        drifting = false
    end

    // control de aceleración al correr
    if (CheckInput("run") and (CheckInput("left") or CheckInput("right")) and !drifting):
        if (run_speed < 450):
            run_speed += 10.71
        end
    elif (!drifting):
        run_speed = 0
    end

    // si entra en derrape se reinicia el impulso acumulado
    if (drifting):
        run_speed = 0
    end

    // salto (diferente cuando corres) 
    if (CheckInput("jump") and IsOnFloor()):
        started_jumping = true
        if (crouching):
            crouch_jump = true
        end
        if (run_speed >= 450):
            AddSpeedY(-1570)
        else
            AddSpeedY(-1400)
        end
        drifting = false
    end

    // movimiento de lado a lado 
    if (!crouching or !IsOnFloor() or crouch_jump):
        // derrape skid
        if (drifting and IsOnFloor()):
            GetComponent("").speed_x *= 0.95
            is_moving = false

            // Invertir orientación del sprite 
            if (GetComponent("").speed_x > 0):
                GetComponent("WalkAnim").SetFlipX(true)
            else
                GetComponent("WalkAnim").SetFlipX(false)
            end

        // mover a la izquierda
        elif (CheckInput("left")):
            if (IsOnFloor()):
                GetComponent("WalkAnim").SetFlipX(true)
            end

            if (crouching and !IsOnFloor()):
                GetComponent("").speed_x = -(360 + (run_speed * 0.8))
            elif (!IsOnFloor() and GetComponent("").speed_x > 0):
                // En el aire
                GetComponent("").speed_x *= 0.90
            else
                GetComponent("").speed_x = -450 - run_speed
            end
            is_moving = true

        // mover a la derecha
        elif (CheckInput("right")):
            if (IsOnFloor()):
                GetComponent("WalkAnim").SetFlipX(false)
            end

            if (crouching and !IsOnFloor()):
                GetComponent("").speed_x = 360 + (run_speed * 0.8)
            elif (!IsOnFloor() and GetComponent("").speed_x < 0):
                // En el aire
                GetComponent("").speed_x *= 0.90
            else
                GetComponent("").speed_x = 450 + run_speed
            end
            is_moving = true

        // desaceleracion al detenerse
        else
            GetComponent("").speed_x *= 0.90
        end
    else
        // friccion al agacharse en suelo:
        if (run_speed >= 300 or GetComponent("").speed_x > 300 or GetComponent("").speed_x < -300):
            GetComponent("").speed_x *= 0.975
        else
            GetComponent("").speed_x *= 0.90
        end
    end

    // salto de altura variable (no encuentro como llamarle)
    if (!IsOnFloor() and !CheckInput("jump") and GetComponent("").speed_y < 0):
        GetComponent("").speed_y *= 0.89
    end

    // Obtener la velocidad absoluta en  x para calcular la animación
    abs_speed_x = GetComponent("").speed_x
    if (abs_speed_x < 0):
        abs_speed_x *= -1
    end

    // animaciones
    if (crouching):
        // (ordenado por prioridad eh)
        if (GetComponent("WalkAnim").GetAnim() != "crouch"):
            GetComponent("WalkAnim").Play("crouch")
        end
    elif (!IsOnFloor()):
        if (started_jumping):
            if (GetComponent("WalkAnim").GetAnim() != "jump"):
                GetComponent("WalkAnim").Play("jump")
            end
        else
            // Si cae sin haber saltado, congela la animación en el frame actual
            GetComponent("WalkAnim").Stop()
        end
    elif (drifting):
        if (GetComponent("WalkAnim").GetAnim() != "skid"):
            GetComponent("WalkAnim").Play("skid")
        end
    elif (is_moving or abs_speed_x > 50):
        if (GetComponent("WalkAnim").GetAnim() != "walk"):
            GetComponent("WalkAnim").Play("walk")
        end

        // velocidad de la animación según la velocidad de movimiento
        walk_fps = 4 + ((abs_speed_x / 900) * 16)
        GetComponent("WalkAnim").ChangeFPS("walk", walk_fps)
    else
        if (GetComponent("WalkAnim").GetAnim() != "idle"):
            GetComponent("WalkAnim").Play("idle")
        end
    end
end
